import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { reduceEvents } from '../receipt-report.js';

const MODULE = join(dirname(fileURLToPath(import.meta.url)), '..', 'receipt-report.js');
const jsonl = events => events.map(e => JSON.stringify(e)).join('\n');

test('empty string and lone newline', () => {
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents('\n'), { jobs: [], duplicates: 0 });
});

test('CRLF and missing final newline', () => {
  const text =
    JSON.stringify({ id: 'a', job: 'j', attempt: 1, seq: 0, type: 'started' }) +
    '\r\n' +
    JSON.stringify({ id: 'b', job: 'j', attempt: 1, seq: 1, type: 'failed' });
  assert.deepEqual(reduceEvents(text), {
    jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'failed', startedSeq: 0, finishedSeq: 1 }] }],
    duplicates: 0,
  });
});

test('every extra copy counts as a duplicate', () => {
  const e = { id: 's', job: 'x', attempt: 1, seq: 0, type: 'started' };
  assert.equal(reduceEvents(jsonl([e, e, e, { ...e, extra: 1 }])).duplicates, 3);
});

test('repeated id with a different required field is an error', () => {
  const e = { id: 's', job: 'x', attempt: 1, seq: 0, type: 'started' };
  assert.throws(() => reduceEvents(jsonl([e, { ...e, seq: 1 }])));
  assert.throws(() => reduceEvents(jsonl([e, { ...e, job: 'y' }])));
});

test('jobs sort by UTF-16 code units, attempts numerically', () => {
  const events = [];
  for (const [job, attempt] of [['Z', 10], ['Z', 2], ['a', 1], ['\u{1F600}', 1], ['Ａ', 1]]) {
    events.push({ id: `${job}-${attempt}`, job, attempt, seq: 0, type: 'started' });
  }
  assert.deepEqual(
    reduceEvents(jsonl(events)).jobs.map(j => j.job),
    // '\u{1F600}' is the surrogate pair D83D DE00, so it precedes 'Ａ' (FF21) by code unit
    // even though its code point is larger — locale collation would order these differently.
    ['Z', 'a', '\u{1F600}', 'Ａ']
  );
  assert.deepEqual(
    reduceEvents(jsonl(events)).jobs.find(j => j.job === 'Z').attempts.map(a => a.attempt),
    [2, 10]
  );
});

test('__proto__ ids and jobs are ordinary strings', () => {
  const out = reduceEvents(jsonl([
    { id: '__proto__', job: '__proto__', attempt: 1, seq: 0, type: 'started' },
    { id: 'constructor', job: '__proto__', attempt: 1, seq: 4, type: 'succeeded' },
  ]));
  assert.deepEqual(out, {
    jobs: [{ job: '__proto__', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 4 }] }],
    duplicates: 0,
  });
});

test('attempt gaps are allowed and attempts are independent', () => {
  const out = reduceEvents(jsonl([
    { id: 'a', job: 'j', attempt: 1, seq: 100, type: 'started' },
    { id: 'b', job: 'j', attempt: 1, seq: 200, type: 'succeeded' },
    { id: 'c', job: 'j', attempt: 7, seq: 5, type: 'started' },
    { id: 'd', job: 'j', attempt: 7, seq: 6, type: 'failed' },
  ]));
  assert.deepEqual(out.jobs[0].attempts, [
    { attempt: 1, status: 'succeeded', startedSeq: 100, finishedSeq: 200 },
    { attempt: 7, status: 'failed', startedSeq: 5, finishedSeq: 6 },
  ]);
});

test('different events may share a seq', () => {
  assert.equal(reduceEvents(jsonl([
    { id: 'a', job: 'x', attempt: 1, seq: 3, type: 'started' },
    { id: 'b', job: 'y', attempt: 1, seq: 3, type: 'started' },
  ])).jobs.length, 2);
});

test('structural violations are errors', () => {
  const start = { id: 's', job: 'j', attempt: 1, seq: 5, type: 'started' };
  // two starts, distinct ids
  assert.throws(() => reduceEvents(jsonl([start, { ...start, id: 's2' }])));
  // two terminals
  assert.throws(() => reduceEvents(jsonl([
    start,
    { id: 't1', job: 'j', attempt: 1, seq: 6, type: 'succeeded' },
    { id: 't2', job: 'j', attempt: 1, seq: 7, type: 'succeeded' },
  ])));
  // contradictory terminals
  assert.throws(() => reduceEvents(jsonl([
    start,
    { id: 't1', job: 'j', attempt: 1, seq: 6, type: 'succeeded' },
    { id: 't2', job: 'j', attempt: 1, seq: 7, type: 'failed' },
  ])));
  // terminal seq not strictly greater
  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 5, type: 'succeeded' }])));
  assert.throws(() => reduceEvents(jsonl([start, { id: 't', job: 'j', attempt: 1, seq: 4, type: 'succeeded' }])));
});

test('field validation rejects bad values without coercion', () => {
  const base = { id: 's', job: 'j', attempt: 1, seq: 0, type: 'started' };
  const bad = [
    { ...base, id: '' }, { ...base, id: 1 }, { ...base, job: '' }, { ...base, job: null },
    { ...base, attempt: 0 }, { ...base, attempt: -1 }, { ...base, attempt: 1.5 },
    { ...base, attempt: '1' }, { ...base, attempt: true },
    { ...base, seq: -1 }, { ...base, seq: '0' }, { ...base, seq: 1.5 },
    { ...base, seq: Number.MAX_SAFE_INTEGER + 2 },
    { ...base, type: 'Started' }, { ...base, type: 'running' }, { ...base, type: 5 },
  ];
  for (const event of bad) assert.throws(() => reduceEvents(jsonl([event])), `${JSON.stringify(event)}`);
  for (const field of ['id', 'job', 'attempt', 'seq', 'type']) {
    const missing = { ...base };
    delete missing[field];
    assert.throws(() => reduceEvents(jsonl([missing])), field);
  }
  for (const line of ['null', '[]', '"x"', '3', 'true', '{bad']) {
    assert.throws(() => reduceEvents(line));
  }
});

test('CLI prints the report and exits 0', () => {
  const dir = mkdtempSync(join(tmpdir(), 'receipt-'));
  const file = join(dir, 'log.jsonl');
  writeFileSync(file, jsonl([
    { id: 'a', job: 'j', attempt: 1, seq: 0, type: 'started' },
    { id: 'b', job: 'j', attempt: 1, seq: 1, type: 'succeeded' },
  ]) + '\n');
  const out = execFileSync(process.execPath, [MODULE, file], { encoding: 'utf8' });
  assert.equal(out, JSON.stringify({
    jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 1 }] }],
    duplicates: 0,
  }) + '\n');
});

const cliFailure = argv => {
  try {
    execFileSync(process.execPath, [MODULE, ...argv], { encoding: 'utf8' });
  } catch (error) {
    return error;
  }
  assert.fail(`expected failure for ${JSON.stringify(argv)}`);
};

test('CLI failures exit 2 with stderr and no stdout', () => {
  const dir = mkdtempSync(join(tmpdir(), 'receipt-'));
  const badFile = join(dir, 'bad.jsonl');
  writeFileSync(badFile, '{bad\n');
  for (const argv of [[], ['a', 'b'], [join(dir, 'missing.jsonl')], [badFile]]) {
    const error = cliFailure(argv);
    assert.equal(error.status, 2);
    assert.equal(error.stdout, '');
    assert.ok(error.stderr.length > 0);
  }
});

test('importing the module does not run the CLI', () => {
  const out = execFileSync(
    process.execPath,
    ['--input-type=module', '-e', `import(${JSON.stringify(MODULE)}).then(m => process.stdout.write(typeof m.reduceEvents))`],
    { encoding: 'utf8' }
  );
  assert.equal(out, 'function');
});

